// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        vm.assume(depositAmount > 0 && depositAmount < type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(minSum <= depositAmount);

        // Setup: set MinSum and LogFile (dummy address)
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Attempt collect
        vm.prank(caller);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.balances(caller);

        assertTrue(balanceAfter <= balanceBefore, "Balance should not increase after Collect");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 initialBalance, uint256 depositAmount, uint256 collectAmount) public {
        // Restrict inputs to avoid overflow and ensure meaningful test
        vm.assume(sender != address(0));
        vm.assume(initialBalance <= type(uint128).max);
        vm.assume(depositAmount <= type(uint128).max);
        vm.assume(collectAmount <= type(uint128).max);

        // Set up: fund the contract and give sender initial balance
        vm.deal(address(c), 10 ether);

        // Initialize contract (only once)
        c.SetMinSum(0);
        c.SetLogFile(address(0)); // dummy log, not used for assertion
        c.Initialized();

        // Mint some balance for sender through Deposit
        vm.prank(sender);
        vm.deal(sender, initialBalance + depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        // Record total supply (contract balance)
        uint256 supplyBefore = address(c).balance;

        // Make a collect attempt
        vm.prank(sender);
        (bool success, bytes memory data) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // After the call, total supply must not have increased (if collect succeeded, supply decreases)
        uint256 supplyAfter = address(c).balance;

        // The invariant: supplyAfter <= supplyBefore (it never increases due to Collect)
        assertTrue(supplyAfter <= supplyBefore, "Supply increased, which indicates balance was added instead of subtracted");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 deposit, uint256 collectAm) public {
        vm.assume(caller != address(0));
        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        // Deposit funds as caller
        vm.deal(caller, deposit);
        vm.prank(caller);
        c.Deposit{value: deposit}();

        // Bound collect amount to not exceed balance (otherwise the call would revert)
        uint256 balance = c.balances(caller);
        collectAm = bound(collectAm, 0, balance);

        // Record balance before Collect
        uint256 balBefore = c.balances(caller);

        // Perform Collect
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAm));

        // If collect succeeded (it should when balance >= collectAm and MinSum <= balance)
        if (ok) {
            uint256 balAfter = c.balances(caller);
            // Rule: balAfter == balBefore - collectAm
            assertTrue(balAfter == balBefore - collectAm, "Balance should decrease by collect amount");
        } else {
            // If it reverted, rule holds trivially (no state change)
            assertTrue(true);
        }
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

