pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 collectAmount) public {
        // Restrict inputs: depositAmount must be non-zero and collectAmount must be <= depositAmount
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max - 1 ether);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit from user
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Deposit{value: depositAmount}();

        // Record balance after deposit
        uint256 balanceAfterDeposit = c.balances(user);

        // Now call Collect with collectAmount
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // General rule: after Deposit, the user's balance is at least the deposited amount
        // This holds for all inputs in the reference (balances[user] += msg.value),
        // but fails in the buggy version where the balance is not increased.
        assertTrue(balanceAfterDeposit >= depositAmount);
    }
}

