pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmt, uint256 collectAmt) public {
        // Bound inputs to reasonable ranges to avoid overflows
        depositAmt = bound(depositAmt, 0, 1e30);
        collectAmt = bound(collectAmt, 0, 1e30);

        // Ensure sender is not zero address (to avoid issues with call)
        vm.assume(sender != address(0));

        // Initialize contract (required to set MinSum)
        c.SetMinSum(0);
        c.Initialized();

        // Record balances before deposit
        uint256 balanceBeforeDeposit = address(c).balance;
        uint256 userBalBeforeDeposit = c.balances(sender);

        // Deposit
        vm.deal(sender, depositAmt);
        vm.prank(sender);
        c.Deposit{value: depositAmt}();

        uint256 balanceAfterDeposit = address(c).balance;
        uint256 userBalAfterDeposit = c.balances(sender);

        // Verify deposit worked as expected in reference
        assertTrue(userBalAfterDeposit == userBalBeforeDeposit + depositAmt);
        assertTrue(balanceAfterDeposit == balanceBeforeDeposit + depositAmt);

        // Now attempt Collect
        // Give contract enough ETH to send back if needed
        uint256 neededETH = collectAmt > userBalAfterDeposit ? 0 : collectAmt;
        if (neededETH > address(c).balance) {
            vm.deal(address(c), neededETH);
        }

        vm.prank(sender);
        (bool ok, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // The rule: after Collect, the sum of (balances[sender] + address(c).balance) is preserved
        // compared to before the Collect call, minus the amount actually transferred to sender if Collect succeeded
        uint256 newUserBal = c.balances(sender);
        uint256 newContractBal = address(c).balance;

        // Calculate expected sum after Collect if it succeeded
        // Before Collect: userBalAfterDeposit + balanceAfterDeposit
        // After Collect: newUserBal + newContractBal + (amount sender actually received)
        // For reference, if Collect succeeds, sender receives collectAmt, so:
        // newUserBal + newContractBal + collectAmt == userBalAfterDeposit + balanceAfterDeposit
        uint256 totalBefore = userBalAfterDeposit + balanceAfterDeposit;
        uint256 totalAfter = newUserBal + newContractBal;

        if (ok) {
            // If Collect succeeded, the sender should have received collectAmt
            // So totalAfter + collectAmt should equal totalBefore
            assertTrue(totalAfter + collectAmt == totalBefore);
        } else {
            // If Collect reverted, balances unchanged
            assertTrue(totalAfter == totalBefore);
        }
    }
}

