pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address user1,
        address user2,
        uint256 deposit1,
        uint256 deposit2,
        uint256 collectAmt,
        address collector
    ) public {
        // Bound deposit amounts to reasonable values
        deposit1 = bound(deposit1, 1 ether, 1000 ether);
        deposit2 = bound(deposit2, 1 ether, 1000 ether);
        collectAmt = bound(collectAmt, 0, deposit1 + deposit2);

        // Ensure collector is one of the users (since Contract uses msg.sender in Collect)
        vm.assume(collector == user1 || collector == user2);

        // Initialize the contract (set MinSum to 0 so Collect can succeed)
        c.SetMinSum(0);
        c.Initialized();

        // Two users deposit ETH
        vm.deal(user1, deposit1);
        vm.prank(user1);
        c.Deposit{value: deposit1}();

        vm.deal(user2, deposit2);
        vm.prank(user2);
        c.Deposit{value: deposit2}();

        // Capture total IN (sum of deposits) and current contract balance before Collect
        uint256 totalIn = deposit1 + deposit2;
        uint256 contractBalBefore = address(c).balance;

        // Call Collect from the chosen collector
        vm.prank(collector);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));
        // Ignore revert; we only care about state after call
        vm.assume(success); // Only consider non-reverting Collect calls for meaningful state check

        // Read balances of both users
        uint256 bal1 = c.balances(user1);
        uint256 bal2 = c.balances(user2);
        uint256 sumBals = bal1 + bal2;

        // Compute total ETH ever sent out via Collect: contractBalBefore - address(c).balance (in ETH sent)
        uint256 ethOut = address(c).balance < contractBalBefore ? contractBalBefore - address(c).balance : 0;

        // General rule: sum of all balances cannot exceed totalIn minus total sent out so far (plus current contract balance)
        // Equivalent to: sumBals <= totalIn - ethOut
        assertTrue(sumBals <= totalIn + contractBalBefore - address(c).balance);
    }
}

