pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        // Bound inputs to avoid overflow/revert
        depositAmount = bound(depositAmount, 0, 1e18);
        minSum = bound(minSum, 0, 1e18);
        collectAmount = bound(collectAmount, 0, 1e18);
        vm.assume(caller != address(0));

        // Setup: initialize and set MinSum
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        uint256 balanceAfter;
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
            balanceAfter = c.balances(caller);
        } catch {
            reverted = true;
            balanceAfter = c.balances(caller);
        }

        // General rule: balance either stays same (if collect fails or condition not met) or decreases by collectAmount
        if (reverted || balanceBefore < minSum || balanceBefore < collectAmount) {
            assertTrue(balanceAfter == balanceBefore, "Balance unchanged when condition fails");
        } else {
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance decreases by collectAmount");
        }
    }
}

