pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address caller,
        uint256 minSum,
        uint256 depositAmount,
        uint256 collectAmount
    ) public {
        // Restrict inputs to avoid overflow and ensure meaningful test
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2);
        vm.assume(collectAmount <= depositAmount);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // If Collect should have succeeded (balance >= minSum and >= collectAmount)
        if (balanceBefore >= minSum && balanceBefore >= collectAmount) {
            assertTrue(success, "Collect should have succeeded");
            uint256 balanceAfter = c.balances(caller);
            // The key property: balance decreases by collectAmount
            assertTrue(balanceAfter == balanceBefore - collectAmount, "Balance should decrease by withdrawn amount");
        }
        // If Collect should have failed, we just verify it reverted or no change
    }
}

