        uint256 logLenBefore = c.Log().History.length();

        // Step 3: Call Collect
        (bool collectOk,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _am));

        // Step 4: Check the rule — the log should have grown (since Deposit added a log entry)
