contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 amount, uint256 minSum) public {
        vm.assume(caller != address(0));
        vm.assume(amount >= 1 && amount <= 1e30);
        vm.assume(minSum >= 0 && minSum <= 1e30);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0x1234));
        c.Initialized();

        // Give caller some ETH
        vm.deal(caller, amount * 2);

        // Deposit some amount
        vm.prank(caller);
        c.Deposit{value: amount}();

        // Try to collect a portion
        uint256 collectAmount = amount / 2;
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Sum all balances (we can only read caller's balance via public getter)
        uint256 callerBalance = c.balances(caller);
        uint256 contractBalance = address(c).balance;
        uint256 minSumVal = c.MinSum();

        // The rule: after a Collect call (whether successful or not), 
        // the caller's balance in the mapping is never greater than the contract's ether balance
        // when the contract balance is at least minSum (because Collect only works when balance >= minSum)
        bool reverted = !success;
        // Only check the rule if the Collect would have been allowed (balance >= minSum and balance >= collectAmount)
        if (callerBalance >= minSumVal && callerBalance >= collectAmount && !reverted) {
            // After a successful Collect, the contract balance decreases by collectAmount
            // So contractBalance + callerBalance should equal initial deposit
            // Actually simpler: caller's balance after Collect should be <= original balance
            assertTrue(callerBalance <= amount, "Rule violated: caller balance should not exceed deposit");
        } else {
            // If Collect reverted or conditions not met, nothing should have changed
            // Just check basic invariants
            assertTrue(address(c).balance >= 0, "Contract balance should be non-negative");
        }
    }
}

